// 議事規範（council_rules）錯誤目錄，代碼區段 E6xxx。
var (
	// ErrCouncilRulesFileUnreadable 為規則檔無法讀取或不是合法 JSON。
	//
	// @ai:generated by=claude-opus-5-5 date=2026-11-05
	ErrCouncilRulesFileUnreadable = errors.Define("E6001", 500, "Council rules file unreadable", "council_rules")
	// ErrCouncilRulesInvalid 為規則內容不一致，例如效力與約束力互相矛盾。
	//
	// @ai:generated by=claude-opus-5-5 date=2026-11-05
	ErrCouncilRulesInvalid = errors.Define("E6002", 422, "Council rules are invalid", "council_rules")
	// ErrCouncilRulesImportFailed 為寫入資料庫失敗；交易已回滾。
	//
	// @ai:generated by=claude-opus-5-5 date=2026-11-05
	ErrCouncilRulesImportFailed = errors.Define("E6003", 500, "Council rules import failed", "council_rules")
)

const (
	councilRuleStatusVoid = "失效"
	councilRuleLevelNone  = "無"

	createCouncilRulesSQL = `CREATE TABLE IF NOT EXISTS public.council_rules (
		rule_key text PRIMARY KEY,
		law_name text NOT NULL,
		pcode text,
		article_ref text NOT NULL,
		subject text NOT NULL,
		applies_to text NOT NULL,
		requirement text NOT NULL,
		penalty text NOT NULL,
		enforcement text NOT NULL,
		binding_level text NOT NULL CHECK (binding_level IN ('強', '中', '弱', '無')),
		binding_reason text NOT NULL,
		status text NOT NULL CHECK (status IN ('有效', '有效但經限縮', '失效')),
		status_basis text,
		source_url text NOT NULL,
		reviewed_on date NOT NULL,
		CONSTRAINT council_rules_void_has_no_binding CHECK ((status = '失效') = (binding_level = '無'))
	)`
	commentCouncilRulesSQL = `COMMENT ON COLUMN public.council_rules.binding_level IS
		'約束力為審閱者的綜合判斷，不是法定分類；理由見 binding_reason'`
)

var (
	councilRuleLevels   = map[string]bool{"強": true, "中": true, "弱": true, councilRuleLevelNone: true}
	councilRuleStatuses = map[string]bool{"有效": true, "有效但經限縮": true, councilRuleStatusVoid: true}
	reReviewDate        = regexp.MustCompile(`^\d{4}-\d{2}-\d{2}$`)
)

// LoadCouncilRules 讀取並驗證規則檔。
//
// @ai:generated by=claude-opus-5-5 date=2026-11-05
// @ai:purpose 這份資料會被當成法律依據引用，寫入前要擋下缺欄位或效力矛盾的紀錄
// @ai:input path 規則 JSON 路徑
// @ai:output *models.CouncilRuleSet, error（ErrCouncilRulesFileUnreadable / ErrCouncilRulesInvalid）
// @ai:sideeffect 讀檔
func LoadCouncilRules(path string) (*models.CouncilRuleSet, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, ErrCouncilRulesFileUnreadable.With("path", path).With("reason", err.Error())
	}
	var set models.CouncilRuleSet
	if err := json.Unmarshal(raw, &set); err != nil {
		return nil, ErrCouncilRulesFileUnreadable.With("path", path).With("reason", err.Error())
	}
	invalid := func(reason string) error { return ErrCouncilRulesInvalid.With("path", path).With("reason", reason) }

	if !reReviewDate.MatchString(set.ReviewedOn) {
		return nil, invalid(fmt.Sprintf("invalid reviewed_on %q", set.ReviewedOn))
	}
	if len(set.Rules) == 0 {
		return nil, invalid("no rules")
	}
	seen := make(map[string]bool, len(set.Rules))
	for i := range set.Rules {
		r := &set.Rules[i]
		if r.RuleKey == "" || seen[r.RuleKey] {
			return nil, invalid(fmt.Sprintf("missing or duplicate rule_key %q", r.RuleKey))
		}
		seen[r.RuleKey] = true
		for field, value := range map[string]string{
			"law_name": r.LawName, "article_ref": r.ArticleRef, "subject": r.Subject, "applies_to": r.AppliesTo,
			"requirement": r.Requirement, "penalty": r.Penalty, "enforcement": r.Enforcement,
			"binding_reason": r.BindingReason, "source_url": r.SourceURL,
		} {
			if value == "" {
				return nil, invalid(fmt.Sprintf("%s: missing %s", r.RuleKey, field))
			}
		}
		if !councilRuleLevels[r.BindingLevel] {
			return nil, invalid(fmt.Sprintf("%s: invalid binding_level %q", r.RuleKey, r.BindingLevel))
		}
		if !councilRuleStatuses[r.Status] {
			return nil, invalid(fmt.Sprintf("%s: invalid status %q", r.RuleKey, r.Status))
		}
		// 失效的規定不能帶有約束力，有效的規定也不能標成沒有約束力。
		if (r.Status == councilRuleStatusVoid) != (r.BindingLevel == councilRuleLevelNone) {
			return nil, invalid(fmt.Sprintf("%s: status %q conflicts with binding_level %q", r.RuleKey, r.Status, r.BindingLevel))
		}
		// 失效或被限縮一定要能追到依據，否則無法查證。
		if r.Status != "有效" && r.StatusBasis == "" {
			return nil, invalid(fmt.Sprintf("%s: status %q needs status_basis", r.RuleKey, r.Status))
		}
		r.ReviewedOn = set.ReviewedOn
	}
	return &set, nil
}

