// Import 在單一交易內建表，並以規則檔內容完整取代表內資料；筆數不符時整批回滾。
//
// @ai:generated by=claude-opus-5-5 date=2026-11-05
// @ai:purpose 規則檔移除的紀錄也必須從表裡消失，否則已修正的錯誤效力會繼續被引用
// @ai:input ctx, set 已驗證的規則
// @ai:output 寫入後的筆數, error（ErrCouncilRulesImportFailed）
// @ai:sideeffect 建立 public.council_rules 並覆寫內容
func (s *CouncilRulesService) Import(ctx context.Context, set *models.CouncilRuleSet) (int, error) {
	count := 0
	err := s.db.HypDBTransaction(ctx, func(ctx context.Context, tx bun.Tx) error {
		if _, err := tx.ExecContext(ctx, createCouncilRulesSQL); err != nil {
			return fmt.Errorf("create table: %w", err)
		}
		if _, err := tx.ExecContext(ctx, commentCouncilRulesSQL); err != nil {
			return fmt.Errorf("comment column: %w", err)
		}
		if _, err := tx.NewDelete().Model((*models.CouncilRule)(nil)).Where("TRUE").Exec(ctx); err != nil {
			return fmt.Errorf("clear table: %w", err)
		}
		if _, err := tx.NewInsert().Model(&set.Rules).Exec(ctx); err != nil {
			return fmt.Errorf("insert rules: %w", err)
		}
		var err error
		if count, err = tx.NewSelect().Model((*models.CouncilRule)(nil)).Count(ctx); err != nil {
			return fmt.Errorf("count rules: %w", err)
		}
		if count != len(set.Rules) {
			return fmt.Errorf("row count %d does not match %d rules", count, len(set.Rules))
		}
		return nil
	})
	if err != nil {
		s.log.Error("import council rules failed", "err", err)
		return 0, ErrCouncilRulesImportFailed.With("reason", err.Error())
	}
	return count, nil
}
